INSERT INTO problems(id,tenant_id,slug,title,difficulty,topic,statement,input_format,output_format,constraints_text,sample_input,sample_output,explanation,published) VALUES
('20000000-0000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111','sum-of-array','Sum of an Array','Easy','Arrays','Given an array of integers, calculate the sum of its elements. Use a 64-bit integer for the result.','The first line contains n. The second line contains n space-separated integers.','Print the sum followed by a newline.','1 ≤ n ≤ 100000; -1000000000 ≤ a[i] ≤ 1000000000',E'5\n1 2 3 4 5\n',E'15\n','1 + 2 + 3 + 4 + 5 = 15.',true),
('20000000-0000-4000-8000-000000000002','11111111-1111-4111-8111-111111111111','palindrome-check','Palindrome Check','Easy','Strings','Determine whether a lowercase string reads the same forward and backward.','One non-empty lowercase string.','Print YES if the string is a palindrome, otherwise NO.','1 ≤ length ≤ 100000',E'racecar\n',E'YES\n','Reading racecar in either direction gives the same string.',true),
('20000000-0000-4000-8000-000000000003','11111111-1111-4111-8111-111111111111','maximum-subarray','Maximum Subarray','Medium','Dynamic Programming','Find the largest sum of any non-empty contiguous subarray.','The first line contains n; the second contains n integers.','Print the maximum sum.','1 ≤ n ≤ 100000; -1000000000 ≤ a[i] ≤ 1000000000',E'5\n-2 3 -1 4 -5\n',E'6\n','The subarray [3, -1, 4] has sum 6.',true),
('20000000-0000-4000-8000-000000000004','11111111-1111-4111-8111-111111111111','binary-search','Find the Target','Easy','Binary Search','Find the zero-based index of a target in an ascending sorted array of distinct integers. Return -1 if absent.','First line: n and target. Second line: n sorted integers.','Print the zero-based index or -1.','1 ≤ n ≤ 100000; all values fit signed 32-bit integers',E'5 7\n1 3 5 7 9\n',E'3\n','The target 7 is at index 3.',true);
