INSERT INTO questions VALUES
(gen_random_uuid(),'11111111-1111-4111-8111-111111111111','30000000-0000-4000-8000-000000000001','What is 20% of 250?','["25","40","50","75"]',2,'250 × 20 / 100 = 50.'),
(gen_random_uuid(),'11111111-1111-4111-8111-111111111111','30000000-0000-4000-8000-000000000001','A product costs ₹800 and is sold for ₹1000. What is the profit percentage?','["20%","25%","30%","15%"]',1,'Profit is ₹200. Profit percentage is 200 / 800 × 100 = 25%.'),
(gen_random_uuid(),'11111111-1111-4111-8111-111111111111','30000000-0000-4000-8000-000000000002','What is the average lookup complexity of a hash table?','["O(n)","O(log n)","O(1)","O(n log n)"]',2,'With a good hash function and controlled load factor, average lookup takes constant time.'),
